mapper.update:
UPDATE mk_resource_escrow_bucket
SET available_amount = #{available}, reserved_amount = #{reserved}, consumed_amount = #{consumed},
    returned_amount = #{returned}, version_no = #{version}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND resource_key = #{resourceKey} AND bucket_id = #{bucketId}
  AND version_no = #{expectedVersion} AND fencing_epoch = #{fencingEpoch}

mapper.select:
SELECT tenant_id AS tenantId, application_id AS applicationId
FROM mk_promotion_application
WHERE state_name = 'RESERVED' AND checkout_ref IS NULL
  AND expires_at <= #{now} AND expiry_next_attempt_at <= #{now}
AND tenant_id = #{tenantId}
ORDER BY expires_at LIMIT #{limit}

SELECT expiry_attempts FROM mk_promotion_application
WHERE tenant_id = #{tenantId} AND application_id = #{applicationId}
FOR UPDATE

mapper.update:
UPDATE mk_promotion_application
SET checkout_ref=#{reference}, checkout_trade_tenant=#{tradeTenant}, checkout_funding_receipt=#{receipt}
WHERE tenant_id=#{tenantId} AND application_id=#{applicationId} AND checkout_ref IS NULL AND state_name='RESERVED'

UPDATE mk_reservation_item


        SET reserved_amount = reserved_amount - #{amount}, consumed_amount = consumed_amount + #{amount}


        SET reserved_amount = reserved_amount - #{amount}, released_amount = released_amount + #{amount}


        SET consumed_amount = consumed_amount - #{amount}, refunded_amount = refunded_amount + #{amount}


WHERE tenant_id = #{tenantId} AND application_id = #{applicationId} AND resource_key = #{resourceKey}

    AND consumed_amount >= #{amount}
    AND reserved_amount >= #{amount}

UPDATE mk_reservation_escrow_allocation


        SET reserved_amount = reserved_amount - #{amount}, consumed_amount = consumed_amount + #{amount}


        SET reserved_amount = reserved_amount - #{amount}, released_amount = released_amount + #{amount}


        SET consumed_amount = consumed_amount - #{amount}, refunded_amount = refunded_amount + #{amount}


WHERE tenant_id = #{tenantId} AND application_id = #{applicationId} AND resource_key = #{resourceKey}
  AND bucket_id = #{bucketId}

    AND consumed_amount >= #{amount}
    AND reserved_amount >= #{amount}

