mapper.select:
SELECT l.ledger_id AS ledgerId, l.posting_time_utc AS postingTime, l.application_id AS applicationId, a.campaign_id AS campaignId, l.resource_key AS resourceKey, r.currency_code AS currency, l.operation_name AS operation, l.amount_value AS amount
AND (l.posting_time_utc > #{cursor.postingTime} OR (l.posting_time_utc = #{cursor.postingTime} AND l.ledger_id > #{cursor.ledgerId}))
ORDER BY l.posting_time_utc, l.ledger_id LIMIT #{limit}
